class Solution {
public:
    int maxDistToClosest(vector<int>& seats) {
        int n = seats.size();
        int last_person = -1;
        int max_dist = 0;
        for (int i = 0; i < n; i++) {
            if (seats[i] == 1) {
                if (last_person == -1) {
                    max_dist = i;
                } else {
                    max_dist = max(max_dist, (i - last_person) / 2);
                }
                last_person = i;
            }
        }
        max_dist = max(max_dist, n - 1 - last_person);
        return max_dist;
    }
};

class Solution {
    public int maxDistToClosest(int[] seats) {
        int n = seats.length;
        int lastPerson = -1;
        int maxDist = 0;
        for (int i = 0; i < n; i++) {
            if (seats[i] == 1) {
                if (lastPerson == -1) {
                    maxDist = i;
                } else {
                    maxDist = Math.max(maxDist, (i - lastPerson) / 2);
                }
                lastPerson = i;
            }
        }
        maxDist = Math.max(maxDist, n - 1 - lastPerson);
        return maxDist;
    }
}

var maxDistToClosest = function(seats) {
    const n = seats.length;
    let lastPerson = -1;
    let maxDist = 0;
    for (let i = 0; i < n; i++) {
        if (seats[i] === 1) {
            if (lastPerson === -1) {
                maxDist = i;
            } else {
                maxDist = Math.max(maxDist, Math.floor((i - lastPerson) / 2));
            }
            lastPerson = i;
        }
    }
    maxDist = Math.max(maxDist, n - 1 - lastPerson);
    return maxDist;
};
